-- Create unit_types lookup table
CREATE TABLE unit_types (
    unit_type_id SERIAL PRIMARY KEY,
    unit_type VARCHAR(50) NOT NULL,

	CONSTRAINT unique_unit_type UNIQUE (unit_type)
);

-- Insert distinct unit types

CREATE TABLE stores (
    store_id SERIAL NOT NULL,
    store_name VARCHAR(100) NOT NULL,
    street_address VARCHAR(255) NOT NULL,
    city_address VARCHAR(100) NOT NULL,
    state_address VARCHAR(2) NOT NULL,
    zip_address VARCHAR(10) NOT NULL,
    latitude DECIMAL(9,6) NOT NULL,
    longitude DECIMAL(9,6) NOT NULL,
    date_created DATE NOT NULL,
    last_updated DATE NULL,
    PRIMARY KEY (store_id),
    CONSTRAINT unique_stores UNIQUE (store_name, street_address, zip_address)
);

CREATE TABLE brands (
    brand_id SERIAL NOT NULL,
    brand_name VARCHAR(50) NOT NULL,
    date_created DATE NOT NULL,
    last_updated DATE NULL,

    PRIMARY KEY (brand_id)
);

CREATE TABLE products (
    product_id SERIAL NOT NULL,
    brand_id INT NULL,
    unit_type_id INT NOT NULL,
    product_name VARCHAR(50) NOT NULL,
    date_created DATE NOT NULL,
    last_updated DATE NULL,

    PRIMARY KEY (product_id),
    CONSTRAINT unique_products UNIQUE (product_name, brand_id, unit_type_id),
    FOREIGN KEY (brand_id) REFERENCES brands(brand_id) ON DELETE CASCADE ON UPDATE CASCADE,
	FOREIGN KEY (unit_type_id) REFERENCES unit_types(unit_type_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE users (
    user_id SERIAL NOT NULL,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    email VARCHAR(50) NOT NULL,
    street_address VARCHAR(50) NOT NULL,
    city_address VARCHAR(50) NOT NULL,
    state_address VARCHAR(2) NOT NULL,
    zip_address VARCHAR (6) NOT NULL,
    date_created DATE NOT NULL,
    last_updated DATE NULL,

    PRIMARY KEY (user_id)
);

CREATE TABLE transactions (
    transaction_id SERIAL NOT NULL,
    user_id INT NOT NULL,
    store_id INT NOT NULL,
    product_id INT NOT NULL,
    quantity DECIMAL NOT NULL,
    cost DECIMAL(12, 2) NOT NULL,
    transaction_date DATE NOT NULL,

    PRIMARY KEY (transaction_id),
    FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
    FOREIGN KEY (store_id) REFERENCES stores(store_id) ON DELETE CASCADE ON UPDATE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products(product_id) ON DELETE CASCADE ON UPDATE CASCADE
);

